parameters.jsCode:
/* Setiap aturan yang menentukan apakah sebuah vendor boleh dibayar, dan apakah
   nomor rekeningnya boleh berubah. Urutannya disengaja:

     1. data tidak lengkap    - tidak bisa menilai yang tidak ada
     2. NPWP tidak sah        - identitas pajak salah bentuk, ditolak di depan
     3. vendor ditahan        - halangan hukum, sebelum urusan lain
     4. duplikat              - vendor kembar memecah riwayat dan mengundang bayar ganda;
                                termasuk jenis permintaan yang tidak cocok dengan master:
                                "vendor baru" untuk vendor yang SUDAH ada, atau ganti
                                rekening untuk vendor yang TIDAK ada
     5. nama rekening beda    - rekening atas nama lain adalah bendera merah klasik
     6. pemisahan wewenang    - peminta tidak boleh merangkap penyetuju
     7. jalur permintaan      - ganti rekening lewat email WAJIB dikonfirmasi telepon

   Nomor 7 adalah pasangan dari tahanan BANK_CHANGED di workflow payment run.
   Payment run menahan uangnya; proses inilah yang melepasnya - dan satu-satunya
   pelepasan yang sah adalah telepon ke nomor LAMA yang sudah tersimpan di master,
   bukan nomor mana pun yang tertulis di permintaan itu sendiri. */

const JALUR_AMAN = ['vendor_portal'];

function norm(s){ return String(s||'').toUpperCase()
  .replace(/\b(PT|CV|UD|TBK|PERSERO)\b/g,' ')
  .replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim(); }
function token(s){ return norm(s).split(' ').filter(function(x){ return x.length>2; }); }
function miripNama(a,b){
  const A=token(a), B=token(b);
  if(!A.length||!B.length) return 0;
  let sama=0;
  for(const x of A) if(B.indexOf(x)!==-1) sama++;
  return sama/Math.max(A.length,B.length);
}
function npwpSah(v){
  const d=String(v||'').replace(/[^0-9]/g,'');
  return { digit:d, sah: d.length===15 };
}

const hariIni = new Date().toISOString().slice(0,10);

const master = $('Muat Master Vendor').all().map(function(i){ return i.json; })
  .filter(function(m){ return m && m.vendor; });

const keluar = [];
const npwpDipakai = {};
for (const m of master) {
  const d = npwpSah(m.npwp).digit;
  if (d && d.length===15) npwpDipakai[d] = m.vendor;
}

/* Dibaca lewat nama node, bukan $input: node pemuat master berada di antara
   pemuat permintaan dan node ini, jadi $input berisi baris MASTER, bukan
   permintaan. Tanpa ini mesin diam-diam menilai 6 vendor, bukan 10 permintaan. */
for (const it of $('Muat Permintaan Terbuka').all()) {
  const r = it.json || {};
  const tipe = String(r.request_type||'new');
  const vendor = String(r.vendor||'').trim();
  const legal = String(r.legal_name||'').trim();
  const np = npwpSah(r.npwp);
  const jalur = String(r.channel||'').trim();
  const diminta = String(r.requested_by||'').trim().toLowerCase();

  const adaDiMaster = master.filter(function(m){
    return norm(m.vendor) === norm(vendor); })[0] || null;

  /* Skor kelengkapan: lapangan yang benar-benar dibutuhkan untuk membayar
     seseorang dan untuk bisa menghubunginya lagi kalau ada yang aneh. */
  const wajib = ['legal_name','npwp','bank_name','account_number','account_name','contact_email','contact_phone'];
  const isi = wajib.filter(function(k){ return String(r[k]||'').trim() !== ''; });
  const skor = Math.round(isi.length / wajib.length * 100);
  const hilang = wajib.filter(function(k){ return String(r[k]||'').trim() === ''; });

  /* Duplikat dicari tiga arah: nama mirip, NPWP sama, atau nomor rekening sama.
     Nomor rekening yang sama untuk dua vendor berbeda hampir selalu berarti
     salah satu dari keduanya bukan vendor yang sesungguhnya. */
  let dupNama=null, dupRek=null;
  for (const m of master) {
    if (tipe==='new' && miripNama(m.vendor, vendor) >= 0.6 && norm(m.vendor)!==norm(vendor)) { dupNama = m; break; }
  }
  for (const m of master) {
    if (String(m.account_number||'') === String(r.account_number||'') && norm(m.vendor)!==norm(vendor)) { dupRek = m; break; }
  }
  const dupNpwp = (tipe==='new' && np.sah && npwpDipakai[np.digit] && norm(npwpDipakai[np.digit])!==norm(vendor))
    ? npwpDipakai[np.digit] : null;

  const namaRekCocok = miripNama(r.account_name, legal) >= 0.6;
  const jalurAman = JALUR_AMAN.indexOf(jalur) !== -1;

  let hasil='', kode='', rute='', alasan='', perluCallback=false;

  if (hilang.length) {
    hasil='ditahan'; kode='DATA_INCOMPLETE'; rute='ap_clerk';
    alasan='Kelengkapan '+skor+'%. Belum ada: '+hilang.join(', ')+'. Tidak bisa dinilai sebelum lengkap.';
  } else if (!np.sah) {
    hasil='ditolak'; kode='NPWP_INVALID'; rute='ap_clerk';
    alasan='NPWP '+np.digit.length+' digit, seharusnya 15. Identitas pajak yang salah bentuk tidak boleh masuk master.';
  } else if (adaDiMaster && adaDiMaster.sanctions_flag === true) {
    hasil='ditolak'; kode='SANCTIONS'; rute='legal';
    alasan=vendor+' sedang ditahan: '+String(adaDiMaster.notes||'ditandai pada daftar tahan')+' Legal harus melepas dulu.';
  } else if (tipe==='new' && adaDiMaster) {
    /* Tanpa ini, permintaan "vendor baru" lewat email atas nama vendor yang sudah
       ada lolos semua kontrol - kontrol jalur dan pemisahan wewenang hanya berlaku
       untuk ganti rekening - lalu ditulis ke master menurut nama vendor: rekening
       lama tertimpa dan ditandai terverifikasi tanpa satu telepon pun. */
    hasil='ditolak'; kode='VENDOR_EXISTS'; rute='ap_supervisor';
    alasan=vendor+' sudah ada di master vendor. Permintaan vendor baru tidak boleh menimpa vendor yang sudah ada: '
      +'perubahan rekening harus diajukan sebagai ganti rekening, dan yang tidak lewat portal wajib dikonfirmasi telepon.';
  } else if (tipe==='bank_change' && !adaDiMaster) {
    hasil='ditolak'; kode='VENDOR_NOT_FOUND'; rute='ap_supervisor';
    alasan='Ganti rekening untuk '+vendor+', padahal vendor itu tidak ada di master vendor. Vendor baru harus diajukan sebagai vendor baru.';
  } else if (dupNpwp) {
    hasil='ditahan'; kode='DUPLICATE_NPWP'; rute='ap_supervisor';
    alasan='NPWP '+np.digit+' sudah terdaftar atas nama '+dupNpwp+'. Satu badan pajak, satu baris master.';
  } else if (dupNama) {
    hasil='ditahan'; kode='DUPLICATE_NAME'; rute='ap_supervisor';
    alasan='Namanya '+Math.round(miripNama(dupNama.vendor,vendor)*100)+'% mirip dengan "'+dupNama.vendor
      +'" yang sudah ada. Vendor kembar memecah riwayat pembayaran dan membuka jalan bayar ganda.';
  } else if (dupRek) {
    hasil='ditahan'; kode='DUPLICATE_ACCOUNT'; rute='treasury';
    alasan='Nomor rekening ini sudah dipakai '+dupRek.vendor+'. Dua vendor satu rekening hampir selalu berarti salah satunya bukan vendor sungguhan.';
  } else if (!namaRekCocok) {
    hasil='ditahan'; kode='NAME_MISMATCH'; rute='treasury';
    alasan='Nama rekening "'+String(r.account_name||'')+'" tidak cocok dengan badan usaha "'+legal
      +'". Rekening atas nama perorangan untuk tagihan badan usaha adalah bendera merah klasik.';
  } else if (tipe==='bank_change' && diminta === 'treasury.lead@example.com') {
    hasil='ditahan'; kode='SOD_VIOLATION'; rute='finance_manager';
    alasan='Diminta oleh '+diminta+', yang juga berwenang menyetujui perubahan rekening. Peminta dan penyetuju harus dua orang berbeda.';
  } else if (tipe==='bank_change' && !jalurAman) {
    hasil='ditahan'; kode='CALLBACK_REQUIRED'; rute='treasury'; perluCallback=true;
    alasan='Permohonan ganti rekening masuk lewat '+jalur+', bukan portal vendor. Telepon '+vendor
      +' memakai nomor LAMA yang tersimpan di master - jangan memakai nomor mana pun yang tertulis di permintaan ini - lalu catat konfirmasinya.';
  } else {
    hasil='disetujui'; kode=''; rute='ap_clerk';
    alasan = tipe==='bank_change'
      ? 'Ganti rekening lewat portal vendor, data lengkap, nama rekening cocok, peminta bukan penyetuju.'
      : 'Vendor baru lolos seluruh pemeriksaan. Kelengkapan '+skor+'%.';
  }

  keluar.push({ json: {
    log_key: 'VLOG-'+String($execution.id||'manual')+'|'+String(r.request_key||''),
    request_key: String(r.request_key||''), vendor: vendor, request_type: tipe,
    outcome: hasil, risk_code: kode, reason: alasan, route_to: rute,
    requested_by: diminta, decided_on: hariIni,
    callback_required: perluCallback, callback_by: '', callback_on: '', callback_number_used: '',
    quality_score: skor, execution_id: String($execution.id||'manual'),
    legal_name: legal, npwp: np.digit, bank_name: String(r.bank_name||''),
    account_number: String(r.account_number||''), account_name: String(r.account_name||''),
    contact_email: String(r.contact_email||''), contact_phone: String(r.contact_phone||''),
    channel: jalur,
    nomor_lama_untuk_telepon: adaDiMaster ? String(adaDiMaster.account_number||'') : '',
    ada_di_master: adaDiMaster ? true : false
  }});
}
return keluar;

