/* Dihitung dari baris yang dikembalikan tabel, bukan dari niat mesin. */
function n(a){ return a.length; }
const semua = $('Kumpulkan Keputusan').all().map(function(i){ return i.json; });
let ditulis = [];
try { ditulis = $('Tulis Log Perubahan').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { ditulis = []; }
let keMaster = [];
try { keMaster = $('Perbarui Master Vendor').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { keMaster = []; }

const setuju = semua.filter(function(r){ return r.outcome==='disetujui'; });
const tahan  = semua.filter(function(r){ return r.outcome==='ditahan'; });
const tolak  = semua.filter(function(r){ return r.outcome==='ditolak'; });
const callback = semua.filter(function(r){ return r.callback_required === true; });

const perKode = {};
for (const r of semua.filter(function(x){ return x.risk_code; })) {
  if (!perKode[r.risk_code]) perKode[r.risk_code] = { kode:r.risk_code, jumlah:0, pemilik:{} };
  perKode[r.risk_code].jumlah++; perKode[r.risk_code].pemilik[r.route_to] = true;
}

return [{ json: {
  run: 'VLOG-'+String($execution.id||'manual'),
  tanggal: new Date().toISOString().slice(0,10),
  total: semua.length, disetujui: n(setuju), ditahan: n(tahan), ditolak: n(tolak),
  perlu_callback: n(callback),
  log_tertulis: ditulis.length, log_gagal: semua.length - ditulis.length,
  master_diperbarui: keMaster.length,
  skor_rata: semua.length ? Math.round(semua.reduce(function(s,r){ return s+Number(r.quality_score||0); },0)/semua.length) : 0,
  rincian: Object.keys(perKode).map(function(k){
    return { kode:k, jumlah:perKode[k].jumlah, pemilik:Object.keys(perKode[k].pemilik).join(', ') }; })
    .sort(function(a,b){ return b.jumlah-a.jumlah; }),
  daftar: semua.map(function(r){
    return { req:r.request_key, vendor:r.vendor, tipe:r.request_type, hasil:r.outcome,
             kode:r.risk_code, pemilik:r.route_to, alasan:r.reason }; }),
  daftar_callback: callback.map(function(r){
    return { req:r.request_key, vendor:r.vendor, telepon_ke:r.contact_phone,
             rekening_lama:r.nomor_lama_untuk_telepon }; })
}}];

