parameters.jsCode:
/* Konfirmasi telepon adalah SATU-SATUNYA jalan sebuah ganti rekening lewat email
   menjadi rekening yang dibayar: payment run menahan vendor yang rekeningnya berubah
   dan belum diverifikasi, dan hanya konfirmasi terverifikasi di sini yang melepasnya.
   Karena itu konfirmasinya diperiksa, bukan dipercaya:
     - permintaannya harus ada, untuk vendor yang sama, dan sedang menunggu telepon
       (tercatat CALLBACK_REQUIRED di log perubahan)
     - permintaan yang sudah diputuskan lewat telepon tidak bisa diputuskan ulang:
       penyangkalan vendor adalah barang bukti, bukan draf
     - hasilnya harus tegas: verified atau failed
     - penelepon harus tercatat, dan bukan orang yang mengajukan permintaan
     - nomor yang ditelepon harus tercatat, dan bukan nomor yang tertulis di
       permintaan itu sendiri
   Rekening yang diterapkan diambil dari PERMINTAAN, bukan dari isi konfirmasi.
   Versi sebelumnya menulis rekening apa pun yang dikirim bersama konfirmasi ke
   master, dan menandainya terverifikasi. */
const webhook = $('Konfirmasi Telepon (Webhook)').first().json || {};
const b = webhook.body || webhook;
const daftar = Array.isArray(b.confirmations) ? b.confirmations : [];
const hariIni = new Date().toISOString().slice(0,10);
function digit(s){ return String(s||'').replace(/\D/g,''); }
/* Nomor Indonesia dinormalkan: +62 / 62 di depan menjadi 0. Tanpa ini, nomor dari
   permintaan yang ditulis "+62 21 5550 7890" lolos dari pemeriksaan "02155507890". */
function nomorHp(s){ const d = digit(s); return d.indexOf('62') === 0 ? '0' + d.slice(2) : d; }

const permintaan = {};
for (const it of $('Muat Permintaan untuk Telepon').all()) {
  const r = it.json || {};
  if (r.request_key) permintaan[String(r.request_key)] = r;
}
const menunggu = {};
const diputuskan = {};
for (const it of $('Muat Log untuk Telepon').all()) {
  const l = it.json || {};
  if (!l.request_key) continue;
  if (l.risk_code === 'CALLBACK_REQUIRED') menunggu[l.request_key] = l;
  if (String(l.log_key||'').indexOf('VCB-') === 0 && (l.outcome === 'disetujui' || l.outcome === 'ditolak')) diputuskan[l.request_key] = l;
}

function tidakSah(c, alasan) {
  return { json: {
    request_key: String(c.request_key||''), vendor: String(c.vendor||''), request_type: '',
    hasil_telepon: 'tidak_sah', hasil_akhir: 'konfirmasi_ditolak',
    callback_by: String(c.called_by||''), callback_number_used: String(c.number_used||''),
    catatan: String(c.note||''), catatan_akhir: 'KONFIRMASI TIDAK DITERIMA: ' + alasan,
    bank_name: '', account_number: '', account_name: '', decided_on: hariIni
  }};
}

if (!daftar.length) return [tidakSah({}, 'muatan tidak memuat daftar confirmations.')];

const diputuskanDiSini = {};
return daftar.map(function(c){
  const key = String(c.request_key||'').trim();
  const req = permintaan[key];
  const hasil = String(c.result||'').trim().toLowerCase();
  const oleh = String(c.called_by||'').trim();
  const nomor = digit(c.number_used);

  if (!req) return tidakSah(c, 'permintaan ' + (key || '(kosong)') + ' tidak ada.');
  if (String(req.vendor||'').trim().toUpperCase() !== String(c.vendor||'').trim().toUpperCase())
    return tidakSah(c, 'vendor di konfirmasi (' + String(c.vendor||'-') + ') bukan vendor permintaan ' + key + ' (' + req.vendor + ').');
  if (diputuskan[key])
    return tidakSah(c, key + ' sudah diputuskan lewat telepon pada ' + String(diputuskan[key].decided_on||'-')
      + ' dengan hasil ' + diputuskan[key].outcome + ', dan tidak bisa diputuskan ulang.');
  if (diputuskanDiSini[key])
    return tidakSah(c, key + ' sudah diputuskan oleh konfirmasi sebelumnya dalam muatan yang sama.');
  if (!menunggu[key])
    return tidakSah(c, key + ' tidak sedang menunggu konfirmasi telepon.');
  if (hasil !== 'verified' && hasil !== 'failed')
    return tidakSah(c, 'hasil harus "verified" atau "failed", bukan "' + String(c.result||'') + '".');
  if (!oleh) return tidakSah(c, 'nama penelepon kosong.');
  if (oleh.toLowerCase() === String(req.requested_by||'').trim().toLowerCase())
    return tidakSah(c, oleh + ' adalah pengaju permintaan ini dan tidak boleh memverifikasinya sendiri.');
  if (!nomor) return tidakSah(c, 'nomor yang ditelepon tidak dicatat.');
  const nomorPermintaan = nomorHp(req.contact_phone);
  if (nomorPermintaan && nomorHp(c.number_used).indexOf(nomorPermintaan) !== -1)
    return tidakSah(c, 'nomor yang ditelepon (' + String(c.number_used) + ') adalah nomor yang tertulis di permintaan itu sendiri. '
      + 'Telepon harus ke nomor lama yang sudah tersimpan, bukan kontak dari pihak yang meminta perubahan.');
  if (hasil === 'verified' && c.account_number && digit(c.account_number) !== digit(req.account_number))
    return tidakSah(c, 'rekening yang dikonfirmasi (' + String(c.account_number) + ') berbeda dari rekening di permintaan (' + req.account_number + ').');

  diputuskanDiSini[key] = true;
  return { json: {
    request_key: key, vendor: String(req.vendor), request_type: String(req.request_type||''),
    hasil_telepon: hasil,
    callback_by: oleh, callback_number_used: String(c.number_used||''), catatan: String(c.note||''),
    bank_name: String(req.bank_name||''), account_number: String(req.account_number||''),
    account_name: String(req.account_name||''), decided_on: hariIni
  }};
});

/* Dijalankan sesudah Catat Hasil Telepon - cabang yang selalu menerima setiap
   konfirmasi. Versi sebelumnya dijalankan sesudah penerapan ke master: bila tidak
   ada yang terverifikasi, cabang itu tidak jalan dan webhook tidak pernah dibalas -
   persis pada kasus terpenting, saat vendor menyangkal perubahan rekeningnya.
   Cabang penerapan tetap selesai lebih dulu karena posisinya di kanvas lebih atas. */
const semua = $('Kumpulkan Hasil Telepon').all().map(function(i){ return i.json; });
const lolos = semua.filter(function(r){ return r.hasil_telepon === 'verified'; });
const gagal = semua.filter(function(r){ return r.hasil_telepon === 'failed'; });
const tidakSah = semua.filter(function(r){ return r.hasil_telepon === 'tidak_sah'; });
let diterapkan = [];
try { diterapkan = $('Terapkan Rekening Baru').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { diterapkan = []; }
let dicatat = [];
try { dicatat = $('Catat Hasil Telepon').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { dicatat = []; }
return [{ json: {
  diproses: semua.length, lolos: lolos.length, gagal: gagal.length, tidak_sah: tidakSah.length,
  master_diterapkan: diterapkan.length, log_tersimpan: dicatat.length,
  daftar_lolos: lolos.map(function(r){ return { req: r.request_key, vendor: r.vendor, rekening: r.bank_name + ' ' + r.account_number }; }),
  daftar_gagal: gagal.map(function(r){ return { req: r.request_key, vendor: r.vendor, catatan: r.catatan_akhir }; }),
  daftar_tidak_sah: tidakSah.map(function(r){ return { req: r.request_key || '-', vendor: r.vendor || '-', alasan: r.catatan_akhir }; }),
  ringkas: lolos.length + ' terverifikasi, ' + gagal.length + ' GAGAL, ' + tidakSah.length + ' tidak diterima'
}}];
